"""matplotlib.spines — axis spine classes."""

from matplotlib.patches import Patch


class Spine(Patch):
    """Axis spine — the line forming an edge of the axes box. Subclass
    of :class:`Patch` so it inherits the same color/linewidth/visibility
    plumbing as any other patch.
    """

    def __init__(self, axes, spine_type, path, **kwargs):
        super().__init__(**kwargs)
        self.axes = axes
        self.spine_type = spine_type
        self._position = ('outward', 0)
        self._bounds = None
        self._patch_kind = 'line'        # 'line' | 'arc' | 'circle'
        self._patch_geometry = None      # holds (center, radius, …) when set
        self._path = path

    def set_position(self, position):
        """Position can be ('outward', pts), ('axes', frac), ('data', val),
        or one of the shorthands 'center' / 'zero'. Stored verbatim."""
        if isinstance(position, str):
            if position == 'center':
                position = ('axes', 0.5)
            elif position == 'zero':
                position = ('data', 0)
        self._position = tuple(position) if hasattr(position, '__iter__') \
                          and not isinstance(position, str) else position

    def get_position(self):
        return self._position

    def set_bounds(self, low=None, high=None):
        """Restrict the spine to span only ``[low, high]`` of its axis."""
        if low is None and high is None:
            self._bounds = None
        else:
            self._bounds = (low, high)

    def get_bounds(self):
        if self._bounds is None:
            # Default — full axis range.
            return (0, 1)
        return self._bounds

    def set_patch_arc(self, center, radius, theta1, theta2):
        self._patch_kind = 'arc'
        self._patch_geometry = (tuple(center), float(radius),
                                  float(theta1), float(theta2))

    def set_patch_circle(self, center, radius):
        self._patch_kind = 'circle'
        self._patch_geometry = (tuple(center), float(radius))

    def set_patch_line(self):
        self._patch_kind = 'line'
        self._patch_geometry = None


class Spines:
    def __init__(self, **kwargs):
        self._spines = kwargs

    def __getitem__(self, key):
        return self._spines.get(key, Spine(None, key, None))

    def __getattr__(self, name):
        if name.startswith('_'):
            raise AttributeError(name)
        return self[name]

    def values(self):
        return self._spines.values()

    def keys(self):
        return self._spines.keys()

    def items(self):
        return self._spines.items()

    @classmethod
    def from_dict(cls, d):
        return cls(**d)


# ─── Added: SpinesProxy from upstream spines.py ─────────────────────


class SpinesProxy:
    """Group-property setter for a collection of spines. Calling
    e.g. ``ax.spines[['top', 'right']].set_visible(False)`` returns a
    SpinesProxy bound to multiple spines; method calls on the proxy
    fan out to every spine in the group.
    """

    def __init__(self, spines):
        self._spines = list(spines)

    def __getattr__(self, name):
        if name.startswith('_'):
            raise AttributeError(name)
        def _fanout(*args, **kwargs):
            for s in self._spines:
                fn = getattr(s, name, None)
                if callable(fn):
                    try: fn(*args, **kwargs)
                    except Exception: pass
            return self
        return _fanout

    def __iter__(self):
        return iter(self._spines)

    def __len__(self):
        return len(self._spines)


# ─── Added: missing Spine methods + classmethod constructors ────────


def _spine_clear(self):
    """Reset the spine to its default state — visible, no custom bounds
    or patch geometry. Mirrors upstream's :meth:`Spine.clear`."""
    self._visible = True
    self._bounds = None
    self._patch_kind = 'line'
    self._patch_geometry = None


def _spine_draw(self, renderer):
    """Plotly handles the actual stroke drawing — no-op here, but
    mirrors upstream's signature so callers can invoke it."""
    pass


def _spine_set_color(self, c):
    """Spines share one color across edges; matplotlib uses this to
    drive both the line and the patch outline."""
    self._color = c
    # Also push through Patch's setters so the patch outline matches.
    try: self.set_edgecolor(c)
    except Exception: pass


def _spine_get_patch_transform(self):
    """Return identity — the plotly backend handles spine placement
    via layout coordinates, not via Patch transforms."""
    from matplotlib.transforms import IdentityTransform
    return IdentityTransform()


def _spine_get_path(self):
    """Return the path the spine renders along. Built from the spine's
    own bounds when set; otherwise falls back to the unit segment."""
    from matplotlib.path import Path
    if self._bounds is not None:
        low, high = self._bounds
        # The actual path depends on spine_type — we approximate as a
        # horizontal / vertical segment.
        if self.spine_type in ('top', 'bottom'):
            y = 0 if self.spine_type == 'bottom' else 1
            return Path([(low, y), (high, y)])
        elif self.spine_type in ('left', 'right'):
            x = 0 if self.spine_type == 'left' else 1
            return Path([(x, low), (x, high)])
    return Path([(0, 0), (1, 1)])


def _spine_get_spine_transform(self):
    from matplotlib.transforms import IdentityTransform
    return IdentityTransform()


def _spine_get_window_extent(self, renderer=None):
    """Bbox spanning the spine's drawn area."""
    from matplotlib.transforms import Bbox
    if self.spine_type in ('top', 'bottom'):
        y = 0 if self.spine_type == 'bottom' else 1
        return Bbox.from_extents(0, y, 1, y)
    if self.spine_type in ('left', 'right'):
        x = 0 if self.spine_type == 'left' else 1
        return Bbox.from_extents(x, 0, x, 1)
    return Bbox.from_extents(0, 0, 1, 1)


def _spine_register_axis(self, axis):
    self.axis = axis

Spine.clear              = _spine_clear
Spine.draw               = _spine_draw
Spine.set_color          = _spine_set_color
Spine.get_patch_transform = _spine_get_patch_transform
Spine.get_path           = _spine_get_path
Spine.get_spine_transform = _spine_get_spine_transform
Spine.get_window_extent  = _spine_get_window_extent
Spine.register_axis      = _spine_register_axis


@classmethod
def _spine_linear(cls, axes, spine_type, **kwargs):
    return cls(axes, spine_type, path=None, **kwargs)


@classmethod
def _spine_arc(cls, axes, spine_type, center, radius, theta1, theta2, **kwargs):
    inst = cls(axes, spine_type, path=None, **kwargs)
    inst._arc = (center, radius, theta1, theta2)
    return inst


@classmethod
def _spine_circular(cls, axes, spine_type, center, radius, **kwargs):
    inst = cls(axes, spine_type, path=None, **kwargs)
    inst._circle = (center, radius)
    return inst


Spine.linear_spine   = _spine_linear
Spine.arc_spine      = _spine_arc
Spine.circular_spine = _spine_circular
